const rows = $input.all().map(item => {
  const normalized = {};

  for (const [key, value] of Object.entries(item.json)) {
    normalized[key.trim()] = value;
  }

  return normalized;
});

const trigger = $('When Executed by Another Workflow').first().json;

const count = (condition) => rows.filter(condition).length;

const leads = count(r => r.lead_id);

const qualifiedLeads = count(
  r => String(r.qualification_status || '').toLowerCase() === 'qualified'
);

const opportunities = count(r => r.opportunity_id);

const won = count(
  r => String(r.opportunity_stage || '').toLowerCase() === 'won'
);

const lost = count(
  r => String(r.opportunity_stage || '').toLowerCase() === 'lost'
);

const quotes = count(r => r.quote_id);

const campaigns = count(r => r.campaign_id);

const appointments = count(r => r.appointment_id);

const followUps = count(r => r.activity_id);

const reviews = count(
  r => r.review_id || r.feedback_id
);

const conversions = won;

const leadQualificationRate =
  leads > 0
    ? Number(((qualifiedLeads / leads) * 100).toFixed(2))
    : 0;

const leadToOpportunityRate =
  leads > 0
    ? Number(((opportunities / leads) * 100).toFixed(2))
    : 0;

const opportunityWinRate =
  opportunities > 0
    ? Number(((won / opportunities) * 100).toFixed(2))
    : 0;

const opportunityLossRate =
  opportunities > 0
    ? Number(((lost / opportunities) * 100).toFixed(2))
    : 0;

const quoteToOpportunityRate =
  opportunities > 0
    ? Number(((quotes / opportunities) * 100).toFixed(2))
    : 0;

const appointmentToOpportunityRate =
  opportunities > 0
    ? Number(((appointments / opportunities) * 100).toFixed(2))
    : 0;

const overallConversionRate =
  leads > 0
    ? Number(((won / leads) * 100).toFixed(2))
    : 0;

return [{
  json: {
    company_id: trigger.company_id || '',
    analysis_type: trigger.analysis_type || '',

    total_leads: leads,
    qualified_leads: qualifiedLeads,

    total_opportunities: opportunities,
    won_opportunities: won,
    lost_opportunities: lost,

    total_quotes: quotes,
    total_appointments: appointments,
    total_follow_ups: followUps,
    total_campaigns: campaigns,
    total_reviews: reviews,

    conversions: conversions,

    lead_qualification_rate: leadQualificationRate,
    lead_to_opportunity_rate: leadToOpportunityRate,
    opportunity_win_rate: opportunityWinRate,
    opportunity_loss_rate: opportunityLossRate,
    quote_to_opportunity_rate: quoteToOpportunityRate,
    appointment_to_opportunity_rate: appointmentToOpportunityRate,
    overall_conversion_rate: overallConversionRate,

    analyzed_at: new Date().toISOString()
  }
}];

const analytics = $('Calculate Analytics').first().json;
const trigger = $('When Executed by Another Workflow').first().json;

const rows = $('Merge All Analytics Data').all().map(item => {
  const normalized = {};

  for (const [key, value] of Object.entries(item.json)) {
    normalized[key.trim()] = value;
  }

  return normalized;
});

const dateFrom = trigger.date_from
  ? new Date(trigger.date_from + 'T00:00:00')
  : null;

const dateTo = trigger.date_to
  ? new Date(trigger.date_to + 'T23:59:59.999')
  : null;

let previousFrom = null;
let previousTo = null;

if (dateFrom && dateTo) {
  const periodLength = dateTo.getTime() - dateFrom.getTime();

  previousTo = new Date(dateFrom.getTime() - 1);
  previousFrom = new Date(previousTo.getTime() - periodLength);
}

function getRowDate(row) {
  const value =
    row.created_at ||
    row.updated_at ||
    row.scheduled_at ||
    row.sent_at;

  if (!value) return null;

  const date = new Date(value);

  return isNaN(date.getTime()) ? null : date;
}

function isBetween(date, from, to) {
  if (!date || !from || !to) return false;

  return date >= from && date <= to;
}

function countRows(rowsToCheck, field, condition = null) {
  return rowsToCheck.filter(row => {
    if (!row[field]) return false;

    if (condition) {
      return condition(row);
    }

    return true;
  }).length;
}

const currentRows = dateFrom && dateTo
  ? rows.filter(row =>
      isBetween(getRowDate(row), dateFrom, dateTo)
    )
  : rows;

const previousRows = previousFrom && previousTo
  ? rows.filter(row =>
      isBetween(getRowDate(row), previousFrom, previousTo)
    )
  : [];

const currentLeads = countRows(currentRows, 'lead_id');

const currentQualifiedLeads = countRows(
  currentRows,
  'lead_id',
  row =>
    String(row.qualification_status || '').toLowerCase() === 'qualified'
);

const currentOpportunities =
  countRows(currentRows, 'opportunity_id');

const currentWon =
  countRows(
    currentRows,
    'opportunity_id',
    row =>
      String(row.opportunity_stage || '').toLowerCase() === 'won'
  );

const previousLeads = countRows(previousRows, 'lead_id');

const previousQualifiedLeads = countRows(
  previousRows,
  'lead_id',
  row =>
    String(row.qualification_status || '').toLowerCase() === 'qualified'
);

const previousOpportunities =
  countRows(previousRows, 'opportunity_id');

const previousWon =
  countRows(
    previousRows,
    'opportunity_id',
    row =>
      String(row.opportunity_stage || '').toLowerCase() === 'won'
  );

function percentageChange(current, previous) {
  if (previous === 0) {
    return current > 0 ? null : 0;
  }

  return Number(
    (((current - previous) / previous) * 100).toFixed(2)
  );
}

return [{
  json: {
    ...analytics,

    trend_period: {
      current_from: trigger.date_from || '',
      current_to: trigger.date_to || '',
      previous_from: previousFrom
        ? previousFrom.toISOString().split('T')[0]
        : '',
      previous_to: previousTo
        ? previousTo.toISOString().split('T')[0]
        : ''
    },

    trends: {
      leads: {
        current: currentLeads,
        previous: previousLeads,
        percentage_change:
          percentageChange(currentLeads, previousLeads)
      },

      qualified_leads: {
        current: currentQualifiedLeads,
        previous: previousQualifiedLeads,
        percentage_change:
          percentageChange(
            currentQualifiedLeads,
            previousQualifiedLeads
          )
      },

      opportunities: {
        current: currentOpportunities,
        previous: previousOpportunities,
        percentage_change:
          percentageChange(
            currentOpportunities,
            previousOpportunities
          )
      },

      won_opportunities: {
        current: currentWon,
        previous: previousWon,
        percentage_change:
          percentageChange(currentWon, previousWon)
      }
    },

    trend_summary: {
      leads_increasing:
        currentLeads > previousLeads,

      qualified_leads_increasing:
        currentQualifiedLeads > previousQualifiedLeads,

      opportunities_increasing:
        currentOpportunities > previousOpportunities,

      wins_increasing:
        currentWon > previousWon
    },

    trends_analyzed_at: new Date().toISOString()
  }
}];

const data = $('Calculate Trends').first().json;

const trends = data.trends || {};

const trendLines = [];

function addTrend(name, trend) {
  if (!trend) return;

  const change = trend.percentage_change;

  if (change === null || change === undefined) {
    return;
  }

  if (typeof change !== 'number') {
    return;
  }

  if (change === 0) {
    trendLines.push(`${name}: unchanged (0% change)`);
  } else if (change > 0) {
    trendLines.push(`${name}: increased by ${change}%`);
  } else {
    trendLines.push(`${name}: decreased by ${Math.abs(change)}%`);
  }
}

addTrend('Leads', trends.leads);
addTrend('Qualified Leads', trends.qualified_leads);
addTrend('Opportunities', trends.opportunities);
addTrend('Won Opportunities', trends.won_opportunities);

return [{
  json: {
    ...data,

    valid_trends:
      trendLines.length > 0
        ? trendLines.join('\n')
        : 'No valid trends can be established because previous-period data is unavailable.'
  }
}];
